-- ============================================================
-- SEED EXT 4: Módulo 19 — Hedging Language (ex 150-220)
-- Novos tópicos: hedging em TOEFL writing avançado, gradações
-- de certeza, hedging com verbos de percepção/cognição,
-- anti-hedging (overclaiming) e sua correção
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'hedging-language';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo hedging-language não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 41: Gradação de certeza (certainty scale)
  (cid,41,150,'multiple_choice','Arrange these from MOST to LEAST certain: "X is the case / X appears to be the case / X may be the case / X is likely the case / X seems to be the case."','Is the case > is likely the case > appears to be the case ≈ seems to be the case > may be the case.','["May > appears > seems > is likely > is","Is > may > appears > seems > is likely","Is the case > is likely the case > appears to be the case ≈ seems to be the case > may be the case.","All are equally certain"]','Certainty scale: is (certain) > likely (probable) > appears/seems (tentative) > may (possible).','hard'),
  (cid,41,151,'gap_fill','The results _____ (suggest) that the intervention _____ (have) a positive effect, although the magnitude of the effect remains _____ (debate/passive).','suggest / has / debated',NULL,'"Suggest" (hedged verb) + simple "has" (PS) + "remains debated" (hedging adjective).','medium'),
  (cid,41,152,'multiple_choice','Which sentence is appropriately hedged for academic writing?','The data appear to indicate a moderate association between the two variables, though the relationship may be mediated by confounding factors.','["The data proves that there is a strong association between the two variables.","The data appear to indicate a moderate association between the two variables, though the relationship may be mediated by confounding factors.","There is definitely a relationship between these two variables.","The data somewhat indicates there might possibly be an association."]','Balanced hedging: appear to indicate + may be mediated = appropriate epistemic caution.','medium'),
  (cid,41,153,'gap_fill','This _____ (suggest) that the original model _____ (need) to be revised, although further research _____ (be) necessary before firm conclusions _____ (draw/passive) can.','suggests / may need / will be / can be drawn',NULL,'Hedged verb + modal + prediction + modal passive.','hard'),
  (cid,41,154,'multiple_choice','Which adverb adds APPROPRIATE epistemic hedge to a finding?','The results tentatively suggest that X is associated with Y.','["The results definitely suggest X is associated with Y (overclaiming).","The results tentatively suggest that X is associated with Y.","The results impossibly suggest X is associated with Y.","The results tentatively is suggesting X associated with Y (grammar error)."]','"Tentatively" hedges the verb "suggest" — double-hedging is standard in careful academic writing.','easy'),

  -- BLOCK 42: Hedging com verbos de percepção e cognição
  (cid,42,155,'gap_fill','The authors _____ (appear) to _____ (underestimate) the role of structural factors in their analysis.','appear / underestimate',NULL,'"Appear + to + base verb" = hedged observation about an author''s approach.','medium'),
  (cid,42,156,'gap_fill','It _____ (seem) that the earlier methodology _____ (introduce) a systematic bias, though this _____ (require) verification.','seems / introduced / requires',NULL,'"It seems" = hedging introductory expression + PS for past bias + PS for current requirement.','medium'),
  (cid,42,157,'multiple_choice','Which verb phrase most STRONGLY hedges a causal claim?','The increase in X is thought to contribute to Y.','["X causes Y (no hedge — certain claim).","X appears to cause Y (moderate hedge — appears).","The increase in X is thought to contribute to Y.","X definitely contributes to Y (certainty — no hedge)."]','"Is thought to" = impersonal epistemic hedge, distancing the claim from the writer.','hard'),
  (cid,42,158,'gap_fill','The mechanism _____ (believe/passive) to _____ (involve) a feedback loop, though direct evidence _____ (yet/present/passive).','is believed / involve / has not yet been presented',NULL,'"Is believed to" = passive epistemic verb + PP negative for missing evidence.','hard'),
  (cid,42,159,'gap_fill','What _____ (seem) clear from the available evidence _____ (be) that the relationship is more complex than originally _____ (assume/passive).','seems / is / assumed',NULL,'"What seems clear" = hedged subject + "is" + "than assumed" = passive hedge.','hard'),
  (cid,42,160,'multiple_choice','Which sentence uses a REPORTING VERB as an epistemic hedge most effectively?','This finding might suggest that the relationship between X and Y is moderated by contextual variables.','["This finding proves that the relationship between X and Y is moderated by contextual variables.","This finding might suggest that the relationship between X and Y is moderated by contextual variables.","This finding shows the relationship between X and Y is moderated by contextual variables.","This finding demonstrates beyond doubt that the relationship is moderated by contextual variables."]','Double hedging: "might" + "suggest" = maximum epistemic caution appropriate for uncertain findings.','medium'),

  -- BLOCK 43: Overclaiming — identificar e corrigir
  (cid,43,161,'multiple_choice','Which sentence is OVERCLAIMING?','This research definitively proves that social media causes depression.','["Research suggests a possible link between social media use and depression symptoms.","This research definitively proves that social media causes depression.","The findings indicate an association between social media use and depression.","Some evidence tentatively supports a relationship between social media use and depression outcomes."]','"Definitively proves" + "causes" = two overclaims. Social science cannot definitively prove causation from correlational data.','easy'),
  (cid,43,162,'gap_fill','Overclaim: "All students who study abroad become more tolerant." → Hedged: "_____ who study abroad _____ (tend/become) more tolerant, _____ differences _____ (likely/reflect) pre-existing orientations."','Students / tend to become / though / likely reflect',NULL,'Hedge: students (not all) + tend to become + though (concession) + likely reflect.','hard'),
  (cid,43,163,'multiple_choice','Which is the BEST hedged version of "Unemployment always causes depression"?','Research consistently indicates that unemployment is associated with elevated rates of depression, though the relationship is moderated by social support and individual resilience.','["Unemployment might sometimes possibly perhaps be linked to depression in some people (over-hedged).","Research consistently indicates that unemployment is associated with elevated rates of depression, though the relationship is moderated by social support and individual resilience.","Unemployment causes some depression in unemployed people most of the time.","Unemployment generally always tends to cause significant depression."]','Appropriate hedging: consistently + associated with + though + moderated by = calibrated claim.','hard'),
  (cid,43,164,'gap_fill','Overclaim: "Technology destroys society." → Hedged: "Technology _____ (appear) to have significant effects on social structures, some of which _____ (may/be) disruptive, _____ careful analysis _____ (suggest) these effects _____ (not/be) uniformly negative."','appears / may be / though / suggests / are not',NULL,'Triple hedge: appears + may be + though + suggests + not uniformly.','hard'),

  -- BLOCK 44: Hedging estrutural (qualificadores, limitadores de escopo)
  (cid,44,165,'gap_fill','_____ the available evidence, it _____ (argue/passive) that the policy _____ (may/have) achieved its intended objectives, at least _____ some contexts.','Based on / can be argued / may have / in',NULL,'"Based on + evidence" + "can be argued" + "may have" + "at least in some" = multi-layer hedging.','hard'),
  (cid,44,166,'multiple_choice','Which phrase LIMITS THE SCOPE of a claim without fully hedging it?','In most high-income countries, access to healthcare has improved significantly.','["Access to healthcare has improved significantly (global claim, no scope limit).","In most high-income countries, access to healthcare has improved significantly.","Access to healthcare might have improved in some countries.","Perhaps access to healthcare has improved somewhat."]','"In most high-income countries" = scope limitation. "Has improved" = confident within that limited scope.','medium'),
  (cid,44,167,'gap_fill','This study focuses primarily on _____ (north/Atlantic) context and _____ (not/intend/passive) to _____ (general) beyond similar political systems.','North Atlantic / is not intended / generalize',NULL,'Scope limitation + passive hedge ("is not intended") + infinitive.','hard'),
  (cid,44,168,'multiple_choice','Which phrase is a TOEFL-appropriate SCOPE LIMITER?','The results of this study are most directly applicable to urban populations in high-income countries.','["The results apply to everyone everywhere.","The results of this study are most directly applicable to urban populations in high-income countries.","The results might possibly apply to some specific populations in certain countries.","The results are definitely applicable to all contexts globally."]','"Most directly applicable to" = scope limitation. Not overly hedged, not overclaimed.','medium'),

  -- BLOCK 45: TOEFL Reading
  (cid,45,169,'multiple_choice','[TOEFL Reading] "It has been proposed that the decline of large predators may have cascading effects on ecosystem dynamics." Which words function as HEDGES?','Has been proposed (passive epistemic) + may have (modal hedge).','["Decline and dynamics","Has been proposed (passive epistemic) + may have (modal hedge).","Large and ecosystem","Cascading and effects"]','Double hedge: passive epistemic verb ("has been proposed") + modal ("may have").','medium'),
  (cid,45,170,'gap_fill','[TOEFL Reading] "The authors _____ that increased screen time _____ be linked to attention deficits, a claim that _____ (need) further empirical _____ (substantiate)." Best hedged forms?','suggest / may / needs / substantiation',NULL,'"Suggest" (hedging verb) + "may be linked" (modal hedge) + "needs substantiation" (limitation).','medium'),
  (cid,45,171,'multiple_choice','[TOEFL Reading] Which sentence from an academic text is APPROPRIATELY hedged?','The evidence suggests that the program was associated with a modest improvement in outcomes, though the effect size was smaller than anticipated.','["The evidence proves beyond doubt that the program improved outcomes dramatically.","The evidence suggests that the program was associated with a modest improvement in outcomes, though the effect size was smaller than anticipated.","The evidence might possibly suggest a very small improvement in some outcomes in some cases.","The evidence does not support any conclusion about outcomes."]','Suggests + associated with + modest + though + smaller than = calibrated academic hedging.','medium'),
  (cid,45,172,'gap_fill','[TOEFL Reading] "While it _____ (be) difficult to _____ (establish) causation from observational data, the consistency of the _____ (find) across multiple studies _____ (strengthens) the _____ (plausible) of the proposed mechanism." Best forms?','is / establish / findings / strengthens / plausibility',NULL,'While + stative "is difficult" + infinitive + nominalization (findings) + hedged conclusion.','hard'),

  -- BLOCK 46: TOEFL Speaking
  (cid,46,173,'production','[TOEFL Speaking — 45s] A reading makes a strong claim about online learning. The lecture presents counterevidence. Summarize using hedging.','',NULL,'The reading argues that online learning is as effective as traditional classroom instruction, citing research showing comparable test score outcomes. The lecture, however, introduces important qualifications to this claim. The professor notes that the studies cited appear to have measured only narrow academic outcomes, and that dimensions of learning that may be equally or more important — social skill development, collaborative problem-solving, and the formation of professional networks — are not easily captured in test scores. The available evidence therefore seems to suggest that online learning may be comparably effective for information transmission but is less clearly effective for the full range of competencies that education is intended to develop. The professor argues that a more nuanced conclusion would be that online and in-person formats may be complementary rather than interchangeable.','hard'),
  (cid,46,174,'production','[TOEFL Speaking — 45s] Discuss whether economic growth is always beneficial for societies. Use hedging to present a balanced academic response.','',NULL,'The relationship between economic growth and broader human welfare appears more complex than a straightforward equation between higher GDP and better outcomes would suggest. The evidence indicates that growth tends to improve material living standards in the long run, but the distribution of those improvements matters enormously, and growth that primarily benefits those already wealthy may do little to reduce poverty or improve the health and education outcomes of the broader population. Research suggests, moreover, that beyond a certain income threshold, additional growth may not substantially improve subjective wellbeing and may be associated with negative outcomes — including environmental degradation, increased inequality, and the erosion of social cohesion — that its aggregate measure does not capture. It therefore seems more accurate to say that growth is a necessary but insufficient condition for broad human welfare, and that the quality of institutions governing distribution is at least as important as the rate of growth itself.','hard'),

  -- BLOCK 47: TOEFL Writing
  (cid,47,175,'production','[TOEFL Writing — 150 words] Write a body paragraph on the effects of social media on democracy. Use appropriate hedging throughout: 3 modal hedges, 2 epistemic verb hedges, 1 scope limitation.','',NULL,'The impact of social media on democratic governance appears to be bidirectional and context-dependent, defying the confident claims of both enthusiastic and pessimistic observers. Research suggests that social media platforms may facilitate political mobilization, particularly among younger and previously disengaged populations, by lowering the organizational costs of collective action and providing new channels for political communication. However, the same platforms appear to enable the rapid spread of misinformation and to contribute to political polarization by algorithmically exposing users primarily to content that confirms their existing beliefs. In most established democracies where research has been conducted, the effects on political attitudes seem more pronounced among already politically engaged populations than among those who might otherwise be less informed. Whether social media represents a net benefit or a net harm for democratic governance may ultimately depend on the regulatory and institutional frameworks within which these platforms operate.','hard'),
  (cid,47,176,'production','[TOEFL Writing — Error Correction] Identify 5 hedging errors: "This study proves that poverty causes crime. All research in this area confirms our hypothesis. The results are 100% reliable. It is obvious that the government made the wrong choice. Anyone can see that inequality is the main cause of social unrest."','',NULL,'proves → suggests / indicates / demonstrates an association; All research confirms → Much research suggests / Evidence broadly supports; 100% reliable → broadly reliable / largely reliable / reliable within stated parameters; It is obvious → It appears / Evidence indicates / It can be argued; Anyone can see → Research suggests / Evidence indicates (academic hedging = evidence-based, not common-sense appeal).','hard'),

  -- BLOCK 48: Consolidação final
  (cid,48,177,'production','[TOEFL Writing — 200 words] Write a body paragraph on the health effects of processed food. Use perfect hedging: appropriate epistemic caution without over-hedging or under-hedging.','',NULL,'The relationship between the consumption of ultra-processed foods and adverse health outcomes has attracted substantial research attention over the past two decades, and the overall weight of evidence appears to support a meaningful association. Epidemiological studies consistently indicate that populations with higher consumption of ultra-processed products tend to have elevated rates of obesity, type 2 diabetes, and cardiovascular disease, even after controlling for total caloric intake and other dietary variables. However, it should be noted that most of this evidence derives from observational studies in which it may be difficult to fully disentangle the effects of processed food consumption from other aspects of dietary pattern, socioeconomic status, and lifestyle. Mechanistic research suggests possible pathways — including the effects of food additives, emulsifiers, and ultra-refined carbohydrates on gut microbiome composition and hormonal satiety signaling — through which processing itself, rather than merely the nutritional profile of these foods, may independently contribute to metabolic dysfunction. The evidence therefore seems sufficient to support public health guidance recommending reduced consumption, while acknowledging that the precise mechanisms and dose-response relationships require further investigation.','hard'),
  (cid,48,178,'production','[TOEFL Speaking — 60s] Discuss the relationship between education and income inequality. Use hedging vocabulary (appear, suggest, may, tend to, seems, is thought to) appropriately throughout.','',NULL,'The relationship between educational attainment and income appears to be one of the most robust patterns in contemporary economic research. In virtually every country for which data exists, higher educational attainment is associated with higher lifetime earnings, and this association seems to have strengthened over the past several decades as economies have shifted toward knowledge-intensive production. However, the interpretation of this pattern is more contested than it might initially appear. Some economists argue that education directly increases productivity — the human capital model — and therefore earnings. Others suggest that education primarily functions as a signal to employers of pre-existing ability or diligence, without necessarily increasing it — the signaling model. Still others contend that the returns to education may have been inflated by credential inflation, as educational requirements for many jobs have risen without clear evidence that the jobs themselves have become more cognitively demanding. What seems clear is that education alone is unlikely to reduce income inequality significantly if structural factors — minimum wages, collective bargaining rights, tax policy, and the concentration of capital income — are not addressed simultaneously.','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
